/* Moniteur JSB — uniquement quatre enregistrements CC0 masterisés.
 * Sources : AUDIO_CREDITS.md. PCM WAV 22050 Hz, mono. Aucun signal ancien.
 * Les 4 sons fonctionnent hors-ligne sur le web et dans l'app native.
 */
(function(root){'use strict';
 const WAV=Object.freeze({
  "buzzerPro":"",
  "bellSport":"",
  "whistlePro":"",
  "hornPro":""
 });
 const api=Object.freeze({
  ids:Object.freeze(Object.keys(WAV)),
  getWavBase64(id){return WAV[id]||null},
  getWavBytes(id){
   const encoded=WAV[id];if(!encoded)return null;
   const binary=typeof atob==='function'?atob(encoded):null;
   if(!binary)return null;
   const bytes=new Uint8Array(binary.length);
   for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);
   return bytes;
  }
 });
 if(typeof module!=='undefined'&&module.exports)module.exports=api;
 root.JSBRealSignals=api;
})(typeof window!=='undefined'?window:globalThis);
